import os
import re

import sublime
import sublime_plugin

from .dsl.report import report

# Editor hints for Trade Stories in Sublime Text: the question a keyword asks,
# shown as ghost text while its predicate is empty, and the mandatory keywords a
# story is still missing, shown under its last line. Also the command behind
# Build, which runs the mechanical verify checks on the open story.
#
# To install, see README.md in this folder.

# >>> generated by extras/editors/build.js from dsl/ - edit dsl/ and rebuild, not this
QUESTIONS = {
    "story": "What are you calling this setup?",
    "trading": "What instrument/market and timeframe is this for?",
    "source": "Which indicators, chart patterns or plotted series does the setup use?",
    "sources": "Which indicators, chart patterns or plotted series does the setup use?",
    "given": "What must already be true for the trade to be considered?",
    "when": "What event or signal triggers entry?",
    "then": "What action does the trade take?",
    "with": "What's the position size? Fixed amount or %? Any leverage?",
    "except": "What invalidates entry even if the trigger fires?",
    "or except": "What invalidates entry even if the trigger fires?",
    "until": "What level (or self-contained set of levels) should the trade be closed at?",
    "or until": "What level (or self-contained set of levels) should the trade be closed at?",
    "taking": "How much profit to take at each level?",
    "sl": "Where's the stop-loss?",
    "unless": "What condition, arising early, exits before target?",
    "or unless": "What condition, arising early, exits before target?",
    "reversed": "Which clauses should be rewritten to allow for a flipped/reversed version of the trade?",
    "reversal": "Which clauses should be rewritten to allow for a flipped/reversed version of the trade?",
    "notes": "What context helps a reader, without being acted on?",
}
MANDATORY = ["story","trading","given","when","then","with","sl","until","taking"]
LABELS = {
    "story": "Story",
    "trading": "Trading",
    "source": "Source",
    "sources": "Sources",
    "given": "Given",
    "when": "When",
    "then": "Then",
    "with": "With",
    "except": "Except",
    "or except": "Or except",
    "and": "And",
    "until": "Until",
    "or until": "Or until",
    "taking": "Taking",
    "sl": "SL",
    "unless": "Unless",
    "or unless": "Or unless",
    "reversed": "Reversed",
    "reversal": "Reversal",
    "notes": "Notes",
}
ALIASES = {
    "sources": "source",
    "reversal": "reversed",
}
KEYWORDS = r"Or\s+except|Or\s+unless|Reversal:|Reversed:|Or\s+until|Reversal|Reversed|Sources|Trading|Except|Notes:|Source|Taking|Unless|Given|Notes|Story|Until|Then|When|With|And|SL"
# <<< generated

# A clause line: a keyword indented by up to 10 spaces, followed by a space or
# the end of the line. The empty form keeps its phantom until the trader types
# the answer, because the pattern insists on nothing but whitespace after it.
CLAUSE_PATTERN = r"(?i)^ {0,10}(" + KEYWORDS + r")(?=\s|$)"
EMPTY_CLAUSE_PATTERN = r"(?i)^ {0,10}(" + KEYWORDS + r")\s*$"

# Sublime minihtml for a hint. color(var(--foreground) alpha(0.4)) follows the
# colour scheme while keeping the hint ghosted, so it is not read as real text.
HINT_HTML = """
<body id="trade-story-hint">
    <style>
        .hint {{
            color: color(var(--foreground) alpha(0.4));
            font-style: italic;
            padding-left: 10px;
        }}
    </style>
    <span class="hint">{text}</span>
</body>
"""


def normalise(line):
    """The keyword a clause line opens with, as the DSL names it."""
    keyword = re.sub(r"\s+", " ", line.strip().lower()).rstrip(":")
    return ALIASES.get(keyword, keyword)


def defaults_file(path):
    """The nearest stories/.settings/defaults.trade above the story, or None."""
    if not path:
        return None
    folder = os.path.dirname(path)
    while True:
        candidate = os.path.join(folder, "stories", ".settings", "defaults.trade")
        if os.path.isfile(candidate):
            return candidate
        parent = os.path.dirname(folder)
        if parent == folder:
            return None
        folder = parent


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def defaults_for(path):
    """Keywords supplied by the nearest stories/.settings/defaults.trade above the story."""
    candidate = defaults_file(path)
    if candidate is None:
        return set()
    try:
        text = read(candidate)
    except OSError:
        return set()
    return {normalise(m.group(0)) for m in re.finditer(CLAUSE_PATTERN, text, re.M)}


class TradeStoryHintsListener(sublime_plugin.ViewEventListener):
    """
    Listens for modifications in views that use the TradeStory syntax and manages
    the display of inline phantom hints.
    """

    @classmethod
    def is_applicable(cls, settings):
        """
        Determines if this listener should be activated for the current file.
        We check the syntax file against the 'TradeStory' name defined in your YAML.
        """
        syntax = settings.get('syntax')
        if not syntax:
            return False
        
        # Matches the provided sublime-syntax file scope or name
        return 'TradeStory' in syntax or 'source.trade' in syntax

    def __init__(self, view):
        super().__init__(view)
        # Initialize a PhantomSet to manage our hints efficiently
        self.phantom_set = sublime.PhantomSet(view, "trade_story_hints")
        self.update_phantoms()

    def on_modified_async(self):
        """Triggered asynchronously whenever the text in the view is modified."""
        self.update_phantoms()
        
    def on_activated_async(self):
        """Triggered when the file is opened or gains focus."""
        self.update_phantoms()

    def update_phantoms(self):
        """
        Renders each empty keyword line's question as an inline phantom after the
        keyword, then lists the mandatory keywords the story is still missing
        under its last line.
        """
        try:
            phantoms = []

            for region in self.view.find_all(EMPTY_CLAUSE_PATTERN):
                keyword = normalise(self.view.substr(region))
                if keyword in QUESTIONS:
                    phantoms.append(sublime.Phantom(
                        sublime.Region(region.end(), region.end()),
                        HINT_HTML.format(text=QUESTIONS[keyword]),
                        sublime.LAYOUT_INLINE
                    ))

            missing = self.missing_mandatory()
            if missing:
                end = self.view.size()
                phantoms.append(sublime.Phantom(
                    sublime.Region(end, end),
                    HINT_HTML.format(text="Missing: " + ", ".join(missing)),
                    sublime.LAYOUT_BLOCK
                ))

            self.phantom_set.update(phantoms)

        except Exception as e:
            # Failsafe error boundary so we don't block the editor if something goes wrong
            print(f"Trade Story Hints Error: {e}")

    def missing_mandatory(self):
        """
        The mandatory keywords absent from the primary story, allowing for the
        ones defaults.trade supplies. Clauses under Reversed and Notes are not
        the story's own, and an empty view has no story to be missing anything.
        """
        present = set()
        for region in self.view.find_all(CLAUSE_PATTERN):
            keyword = normalise(self.view.substr(region))
            if keyword in ("reversed", "notes"):
                break
            present.add(keyword)
        if not present:
            return []
        supplied = present | defaults_for(self.view.file_name())
        return [LABELS[k] for k in MANDATORY if k not in supplied]


class TradeStoryVerifyCommand(sublime_plugin.WindowCommand):
    """
    Build: runs the mechanical verify checks on the story in the active view and
    lists each finding in the build panel, where a click goes to its line.
    """

    def run(self, kill=False):
        if kill:
            return
        panel = self.window.create_output_panel("exec")
        panel.settings().set("result_file_regex", r"^(.+?):(\d+):(?:(\d+):)?\s*(.*)$")
        panel.run_command("append", {"characters": "\n".join(self.findings()) + "\n"})
        self.window.run_command("show_panel", {"panel": "output.exec"})

    def findings(self):
        view = self.window.active_view()
        path = view.file_name() if view else None
        if not path:
            return ["Save the story first, so there is a file to check."]
        settings = defaults_file(path)
        try:
            defaults_text = read(settings) if settings else None
        except OSError as e:
            return [f"Can't read {settings}: {e.strerror}"]
        return report(path, view.substr(sublime.Region(0, view.size())), defaults_text)